"""Small synthetic subtype preflight probe; an encoder spy prevents serialization."""
import json
from pathlib import Path
from sandbox_science.workspace import mathrepair, repair_prompt as p

pin = p.assemble_repair(mathrepair.SYSTEM_PROMPT, 'x', False, 'e').provenance

class Extended(p.RepairProvenance):
    extra_text: str

class Format(p.RequestFormat):
    extra_text: str

fields = pin.model_dump(mode='python')
fields['request_format'] = pin.request_format
outer = Extended.model_construct(**fields, extra_text='x' * 8192)
nested = pin.model_copy(update={'request_format': Format.model_construct(**pin.request_format.model_dump(), extra_text='x' * 8192)})
original = p._canonical
results = []
class Reached(Exception): pass
try:
    for name, value, action in [('outer', outer, p.provenance_json), ('formatter', nested, lambda v: v._pins())]:
        seen = []
        def stop(value):
            seen.append(len(value.get('extra_text', '')) if isinstance(value, dict) else -1)
            raise Reached
        p._canonical = stop
        try: action(value)
        except Reached: results.append({'case': name, 'extra_field_reached_encoder': True, 'extra_bytes': seen})
        except ValueError: results.append({'case': name, 'extra_field_reached_encoder': False, 'refused': True})
        else: raise AssertionError('forged subtype was accepted')
finally: p._canonical = original
print(json.dumps(results, sort_keys=True))

